package dev.eugheist.ttmodern;
import net.minecraft.world.item.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.effect.*;
final class AwakenedLegsAudit {
 static void check(boolean ok,String label){if(!ok)throw new IllegalStateException("TT awakened legs: "+label);}
 static void run(net.minecraft.server.MinecraftServer server){var level=server.overworld();var p=new net.neoforged.neoforge.common.util.FakePlayer(level,new com.mojang.authlib.GameProfile(java.util.UUID.randomUUID(),"LegsAudit")){@Override public boolean isInvulnerableTo(net.minecraft.world.damagesource.DamageSource source){return false;}};p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);try{var f=net.minecraft.server.level.ServerPlayer.class.getDeclaredField("spawnInvulnerableTime");f.setAccessible(true);f.setInt(p,0);}catch(ReflectiveOperationException e){throw new IllegalStateException(e);}p.getAbilities().invulnerable=false;p.setPos(30.5,290,30.5);p.setYRot(0);var stack=new ItemStack(AwakenedLegs.ITEM.get());p.setItemSlot(EquipmentSlot.LEGS,stack);AwakenedArmorStatus.set(p,true);var saved=new java.util.HashMap<net.minecraft.core.BlockPos,net.minecraft.world.level.block.state.BlockState>();for(var pos:AwakenedLegs.lights(p)){saved.put(pos,level.getBlockState(pos));level.setBlock(pos,net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(),2);}
 try{p.setHealth(10);p.invulnerableTime=0;p.hurt(level.damageSources().onFire(),4);check(p.getHealth()==14,"real native fire heals full pre-armor amount: "+p.getHealth());AwakenedArmorItem.toggle(stack);p.setHealth(10);p.invulnerableTime=0;p.hurt(level.damageSources().onFire(),4);check(p.getHealth()==14,"original fire healing ignores individual toggle");AwakenedArmorStatus.set(p,false);p.setHealth(10);p.invulnerableTime=0;p.hurt(level.damageSources().onFire(),4);check(p.getHealth()<10,"global toggle disables healing");AwakenedArmorStatus.set(p,true);AwakenedArmorItem.toggle(stack);p.removeAllEffects();AwakenedLegs.update(p);var effect=p.getEffect(MobEffects.FIRE_RESISTANCE);check(effect!=null&&effect.getDuration()==202&&effect.getAmplifier()==10,"original fire resistance duration and amplifier");for(var pos:AwakenedLegs.lights(p))check(level.getBlockState(pos).is(ThaumicTinkererModern.NITOR_LIGHT.get())&&level.getBlockState(pos).getLightEmission(level,pos)==15,"awakened light emission");p.removeAllEffects();p.addEffect(new MobEffectInstance(MobEffects.FIRE_RESISTANCE,100,2));AwakenedLegs.update(p);check(p.getEffect(MobEffects.FIRE_RESISTANCE).getAmplifier()==2&&p.getEffect(MobEffects.FIRE_RESISTANCE).getDuration()==202,"short existing amplifier retained");p.removeAllEffects();p.addEffect(new MobEffectInstance(MobEffects.FIRE_RESISTANCE,1000,12));AwakenedLegs.update(p);check(p.getEffect(MobEffects.FIRE_RESISTANCE).getDuration()==1000&&p.getEffect(MobEffects.FIRE_RESISTANCE).getAmplifier()==12,"long stronger effect preserved");AwakenedArmorItem.toggle(stack);p.removeAllEffects();AwakenedLegs.update(p);check(!p.hasEffect(MobEffects.FIRE_RESISTANCE),"disabled tick grants no effect");
 var recipe=dev.eugheist.tc4modern.InfusionItemRecipes.all().stream().filter(r->r.key().equals("ICHORCLOTH_LEGS_GEM")).findFirst().orElseThrow();var parts=recipe.componentStacks();check(parts.size()==12&&parts.get(5).is(Items.GOLDEN_CHESTPLATE)&&parts.get(9).is(Items.LAVA_BUCKET),"original twelve components including chestplate quirk");var input=new ItemStack(KamiArmor.ITEMS.get(2).get());check(dev.eugheist.tc4modern.InfusionItemRecipes.match(parts,input,java.util.Set.of(recipe.research()))==recipe,"native potion infusion accepted");parts.set(6,net.minecraft.world.item.alchemy.PotionContents.createItemStack(Items.POTION,net.minecraft.world.item.alchemy.Potions.NIGHT_VISION));check(dev.eugheist.tc4modern.InfusionItemRecipes.match(parts,input,java.util.Set.of(recipe.research()))==null,"wrong potion rejected");var r=thaumcraft.api.research.ResearchCategories.getResearch(recipe.research());check(r.getPages().length==3&&r.displayColumn==17&&r.displayRow==9,"original research progression");System.out.println("TT AWAKENED LEGS AUDIT: ALL PASS (real fire pre-armor healing/toggles,fire resistance refresh,bright lights,original infusion/potion/research)");
 }finally{p.removeAllEffects();p.discard();saved.forEach((pos,state)->level.setBlock(pos,state,2));}
 }
}
